{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello शिवराम जी, आपके 20 mm कबड्डी floor mat की request IndiaMART पर raised है।"
    },
    {
      "i": 1,
      "speaker": "bot",
      "text": "बस उसी के लिए कुछ details confirm करनी थी।"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "मैंने पे कर दी हूँ।"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "2 lakh रुपये आप मार्ज भिजवा दो।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "क्षमा कीजिए मैं समझ नहीं पाया।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "क्या आप अपनी requirement के बारे में बात कर रहे हैं या कुछ और बताना चाहते हैं?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "कृपया मुझे piece के बारे में बताएं वरना हम लोग नहीं ले पाएंगे।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "पैसों और price के बारे में आप सीधे seller से बात कर सकते हैं।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "क्या मैं आपकी call उनसे connect करवा दूं?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "मैं आपकी call उनसे connect करवा दूँ।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "जरूर but पहले बस एक दो details confirm कर लेते हैं ताकि seller आपकी requirement समझ सकें।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "आपको कौन सा mat size चाहिए जैसे 1x1 meter, 1x2 meter या कुछ और?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "one x two meter."
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "क्या आप इस product के बारे में कोई और details या specification share करना चाहेंगे?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "Yes मुझे बस prices के बारे में जानना है।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "जी मैं समझ सकता हूँ।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "आपकी details note कर ली गई है और जल्द ही एक seller आपसे contact करेंगे।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 20,
      "speaker": "caller",
      "text": "आपकी बात का इंतजार करेंगे।"
    }
  ]
}
